sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    c.loading = false;

    c.successMessage = "";

    c.errorMessage = "";


    c.submitTicket = function() {

        c.successMessage = "";
        c.errorMessage = "";


        if (!c.data.category) {

            c.errorMessage =
                "Please select an issue category.";

            return;
        }


        if (!c.data.subject) {

            c.errorMessage =
                "Please enter the subject.";

            return;
        }


        if (!c.data.description) {

            c.errorMessage =
                "Please describe your issue.";

            return;
        }


        c.loading = true;


        c.server.get({

            action: "create_ticket",

            category: c.data.category,

            subject: c.data.subject,

            description: c.data.description

        }).then(function(response) {

            c.loading = false;


            if (response.data.success) {

                c.successMessage =
                    response.data.message;


                c.data.category = "";

                c.data.subject = "";

                c.data.description = "";

            } else {

                c.errorMessage =
                    response.data.message;

            }

        });

    };


    c.goBack = function() {

        window.location.href =
            "?id=student_welcome";

    };

};

sp_widget.css:
.cfms-ticket-page {
    min-height: 100vh;
    background: #f3f6fa;
    padding: 35px;
    font-family: "Segoe UI", Arial, sans-serif;
    color: #102235;
}


.ticket-header {
    background: white;
    border-radius: 16px;
    padding: 25px 30px;
    margin-bottom: 25px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    border: 1px solid #dce4eb;
}


.ticket-header h1 {
    margin: 0 0 7px;
    font-size: 29px;
    font-weight: 750;
}


.ticket-header p {
    margin: 0;
    color: #63768a;
    font-size: 16px;
}


.back-btn {
    border: 1px solid #cfd9e2;
    background: white;
    color: #34506a;
    padding: 10px 18px;
    border-radius: 8px;
    cursor: pointer;
    font-size: 15px;
}


.ticket-card {
    background: white;
    max-width: 850px;
    margin: auto;

    padding: 35px;

    border-radius: 18px;

    border: 1px solid #dce4eb;

    box-shadow:
        0 8px 25px rgba(30, 50, 70, .06);
}


.form-group {
    margin-bottom: 24px;
}


.form-group label {
    display: block;
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 9px;
}


.form-control {
    width: 100%;
    box-sizing: border-box;

    border: 1px solid #ccd7e0;

    border-radius: 9px;

    padding: 13px 15px;

    font-size: 15px;

    background: #ffffff;

    outline: none;
}


.form-control:focus {
    border-color: #159c91;

    box-shadow:
        0 0 0 3px rgba(21,156,145,.10);
}


.description {
    resize: vertical;
}


.submit-btn {
    width: 100%;
    height: 52px;

    border: none;
    border-radius: 9px;

    background: #117f75;

    color: white;

    font-size: 17px;
    font-weight: 700;

    cursor: pointer;
}


.submit-btn:hover {
    background: #096b62;
}


.submit-btn:disabled {
    opacity: .6;
    cursor: not-allowed;
}


.success-message {
    margin-top: 20px;
    padding: 14px;

    border-radius: 8px;

    background: #e7f7ee;
    color: #137442;

    text-align: center;
}


.error-message {
    margin-top: 20px;
    padding: 14px;

    border-radius: 8px;

    background: #fff0f0;
    color: #c62828;

    text-align: center;
}


@media(max-width:600px) {

    .cfms-ticket-page {
        padding: 18px;
    }

    .ticket-header {
        align-items: flex-start;
        gap: 15px;
    }

    .ticket-header h1 {
        font-size: 23px;
    }

    .ticket-card {
        padding: 22px;
    }

}

sp_widget.script:
(function() {

    data.success = false;
    data.message = "";


    if (input && input.action == "create_ticket") {

        if (!input.category ||
            !input.subject ||
            !input.description) {

            data.success = false;
            data.message =
                "Please fill all required fields.";

            return;
        }


        var ticket = new GlideRecord("incident");

        ticket.initialize();


        ticket.caller_id = gs.getUserID();

        ticket.short_description =
            "[CFMS] " + input.subject;

        ticket.description =
            "Category: " + input.category +
            "\n\n" +
            input.description;

        ticket.contact_type = "self-service";

        ticket.urgency = 3;
        ticket.impact = 3;


        var ticketNumber = ticket.insert();


        if (ticketNumber) {

            data.success = true;

            data.number =
                ticket.getValue("number");

            data.message =
                "Ticket " +
                ticket.getValue("number") +
                " has been raised successfully.";

        } else {

            data.success = false;

            data.message =
                "Unable to create the ticket.";

        }

    }

})();
